"""Contact sheet for substitute teachers."""

from typing import List, Sequence, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError

Cells = Tuple[str, str, str]


def _name_key(student: Student) -> Tuple[str, str]:
    return (student.display_name.casefold(), student.student_id)


def _check_email(student: Student) -> None:
    if not student.email:
        raise ProjectError(
            f"no email for {student.display_name}"
        )


def _cells(student: Student) -> Cells:
    name = student.display_name
    return (name, student.section, student.email or "")


def _align(rows: List[Cells]) -> List[str]:
    sizes = [max(map(len, column)) for column in zip(*rows)]
    return [
        "  ".join(
            text.ljust(size) for text, size in zip(row, sizes)
        ).rstrip()
        for row in rows
    ]


def contact_rows(students: Sequence[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    if not students:
        raise ProjectError("no students for the contact sheet")
    ordered = sorted(students, key=_name_key)
    for student in ordered:
        _check_email(student)
    return _align([_cells(student) for student in ordered])
